inline constexpr const char* kTagline =
    "Transient-locked keyframe time stretcher";

inline constexpr const char* kPreamble =
    "Incoming stereo is stretched while its envelope and transients are "
    "tracked in parallel. When a transient passes the threshold, the "
    "lagging read head snaps to the current moment with a short crossfade "
    "and stretches on from there: time stretching that stays locked to "
    "the rhythm of the input. **Pitch and time are fully decoupled, and "
    "can run forwards or backwards independently.** The engine is "
    "[Keyframe Time Stretching via Extrema "
    "Sampling](https://github.com/heavylight-industries/dafx26-paper) "
    "(DAFx26).";

